import { useState } from 'react';
import Sparkline from './Sparkline';

const TICKER_COLORS = {
  HLT: '#10D078',
  WLT: '#F0B429',
  SOC: '#4D9EFF',
};

const TICKER_ICONS = {
  HLT: '♥',
  WLT: '◈',
  SOC: '⬡',
};

const ACTIVITIES = {
  HLT: [
    { type: 'gym_session',  label: 'Gym session',   vtl: '+12' },
    { type: 'run_walk',     label: 'Run / Walk',    vtl: '+8'  },
    { type: 'sleep_logged', label: 'Good sleep',    vtl: '+6'  },
    { type: 'healthy_meal', label: 'Healthy meal',  vtl: '+4'  },
  ],
  WLT: [
    { type: 'sip_active',      label: 'SIP active',      vtl: '+10' },
    { type: 'savings_added',   label: 'Added savings',   vtl: '+12' },
    { type: 'portfolio_check', label: 'Portfolio review', vtl: '+3'  },
  ],
  SOC: [
    { type: 'event_attended',  label: 'Event attended',  vtl: '+10' },
    { type: 'friend_call',     label: 'Called a friend', vtl: '+7'  },
    { type: 'networking_meet', label: 'Networking',       vtl: '+9'  },
  ],
};

export default function StockCard({ stock, onLog, onSync }) {
  const [expanded, setExpanded] = useState(false);
  const [logging, setLogging]   = useState(null);

  const color   = TICKER_COLORS[stock.ticker];
  const icon    = TICKER_ICONS[stock.ticker];
  const isUp    = stock.direction === 'up';
  const isDown  = stock.direction === 'down';
  const acts    = ACTIVITIES[stock.ticker] || [];

  const handleLog = async (type) => {
    setLogging(type);
    await onLog(type);
    setLogging(null);
    setExpanded(false);
  };

  return (
    <div style={{
      background: 'var(--bg-card)',
      border: `1px solid ${expanded ? color + '40' : 'var(--border)'}`,
      borderRadius: 'var(--radius-lg)',
      padding: '24px',
      cursor: 'pointer',
      transition: 'all 0.25s ease',
      animation: 'fadeUp 0.5s ease forwards',
      position: 'relative',
      overflow: 'hidden',
    }}
    onMouseEnter={e => e.currentTarget.style.background = 'var(--bg-card-hover)'}
    onMouseLeave={e => e.currentTarget.style.background = 'var(--bg-card)'}
    onClick={() => setExpanded(v => !v)}
    >
      {/* Ambient glow top-left */}
      <div style={{
        position: 'absolute', top: -40, left: -40,
        width: 120, height: 120,
        borderRadius: '50%',
        background: color,
        opacity: 0.04,
        filter: 'blur(30px)',
        pointerEvents: 'none',
      }}/>

      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div style={{
            width: 36, height: 36, borderRadius: 10,
            background: color + '18',
            border: `1px solid ${color}30`,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: 16, color,
          }}>
            {icon}
          </div>
          <div>
            <div style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 15, color: 'var(--text-primary)', letterSpacing: '0.02em' }}>
              {stock.name}
            </div>
            <div style={{ fontFamily: 'var(--font-mono)', fontSize: 11, color: 'var(--text-secondary)', marginTop: 1 }}>
              {stock.ticker} · {stock.streak_days}d streak
            </div>
          </div>
        </div>

        <div style={{ textAlign: 'right' }}>
          <div style={{ fontFamily: 'var(--font-mono)', fontSize: 22, fontWeight: 500, color, letterSpacing: '-0.01em' }}>
            {stock.price.toFixed(0)}
            <span style={{ fontSize: 11, color: 'var(--text-secondary)', marginLeft: 4 }}>VTL</span>
          </div>
          <div style={{
            fontFamily: 'var(--font-mono)', fontSize: 12, marginTop: 2,
            color: isUp ? 'var(--green)' : isDown ? 'var(--red)' : 'var(--text-secondary)',
          }}>
            {isUp ? '▲' : isDown ? '▼' : '—'} {Math.abs(stock.change_pct).toFixed(2)}%
          </div>
        </div>
      </div>

      {/* Sparkline */}
      <div style={{ marginBottom: 16 }}>
        <Sparkline data={stock.sparkline} color={color} width={260} height={44}/>
      </div>

      {/* Footer */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'var(--font-mono)' }}>
          {stock.last_activity_at
            ? `Last: ${new Date(stock.last_activity_at).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}`
            : 'No activity yet'}
        </div>
        <div style={{
          fontSize: 10, fontFamily: 'var(--font-mono)',
          color: color, background: color + '15',
          padding: '3px 8px', borderRadius: 20,
          border: `1px solid ${color}25`,
        }}>
          {expanded ? 'CLOSE ↑' : 'LOG ↓'}
        </div>
      </div>

      {/* Activity log panel */}
      {expanded && (
        <div style={{
          marginTop: 16,
          paddingTop: 16,
          borderTop: `1px solid var(--border)`,
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          gap: 8,
          animation: 'fadeUp 0.2s ease forwards',
        }}
        onClick={e => e.stopPropagation()}
        >
          {acts.map(a => (
            <button key={a.type}
              disabled={logging === a.type}
              onClick={() => handleLog(a.type)}
              style={{
                background: logging === a.type ? color + '30' : 'var(--bg-base)',
                border: `1px solid ${color}25`,
                borderRadius: 'var(--radius-sm)',
                padding: '10px 12px',
                cursor: 'pointer',
                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                transition: 'all 0.15s',
              }}
              onMouseEnter={e => e.currentTarget.style.background = color + '18'}
              onMouseLeave={e => e.currentTarget.style.background = 'var(--bg-base)'}
            >
              <span style={{ fontFamily: 'var(--font-body)', fontSize: 12, color: 'var(--text-primary)' }}>
                {logging === a.type ? 'Logging...' : a.label}
              </span>
              <span style={{ fontFamily: 'var(--font-mono)', fontSize: 11, color }}>
                {a.vtl} VTL
              </span>
            </button>
          ))}

          {stock.ticker === 'WLT' && (
            <button
              onClick={(e) => { e.stopPropagation(); onSync(); }}
              style={{
                gridColumn: '1 / -1',
                background: 'var(--bg-base)',
                border: `1px solid var(--gold)40`,
                borderRadius: 'var(--radius-sm)',
                padding: '10px 12px',
                cursor: 'pointer',
                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
              }}
              onMouseEnter={e => e.currentTarget.style.background = 'var(--gold-glow)'}
              onMouseLeave={e => e.currentTarget.style.background = 'var(--bg-base)'}
            >
              <span style={{ fontFamily: 'var(--font-body)', fontSize: 12, color: 'var(--text-primary)' }}>
                Sync Groww portfolio
              </span>
              <span style={{ fontFamily: 'var(--font-mono)', fontSize: 11, color: 'var(--gold)' }}>
                AUTO
              </span>
            </button>
          )}
        </div>
      )}
    </div>
  );
}
